// v23.xx (gfx35), HIS ORDER 2026-10-12 (the graphics program, item 9, atmosphere; his answer 20, gritty and grounded): RAIN HITS THE
// GROUND. Rain was one sheet of hairlines in screen space over everything, so it fell on nothing: no water landed anywhere and the
// rain had no depth. Two things now, both under the fog of war sheet (gfxPreFogE) so they dim with the dark you cannot see into:
// - splashes: small rings that open and fade on the ground across the view, about 50 at a time in rain and 80 in a storm (fewer on
//   Effects LOW). Each splash is at a spot hashed from its slot and its cycle of the raid clock (gfxH2), a pure function like the
//   rain hairlines: no random draw, nothing stored. One baked ring sprite (in the store registry), one drawImage each.
// - a far rain layer: a second, fainter and slower set of hairlines behind the near one, so the rain has depth.
// Both fade in and out with a weather turn (they scale with the blended rain), damp at night the way v3.58 and v16.00 damp the
// hairlines, and draw nothing in a clear sky, a bot raid or with GFX.bypass. The near hairlines are untouched.
function gfxH2(a,b){ var s=Math.sin(a*127.1+b*311.7)*43758.5453; return s-Math.floor(s); }
function gfxSplashSpr(){
  var st=gfxStore('gfxE'), m=st.m, c, x;
  if(m.splash) return m.splash;
  c=document.createElement('canvas'); c.width=64; c.height=32; x=c.getContext('2d');
  x.strokeStyle='rgba(214,226,242,.95)'; x.lineWidth=3;
  x.beginPath(); x.ellipse(32,16,28,12,0,0,6.2832); x.stroke();
  x.strokeStyle='rgba(214,226,242,.45)'; x.lineWidth=2;
  x.beginPath(); x.ellipse(32,16,15,6,0,0,6.2832); x.stroke();
  m.splash=c; st.n++;
  return c;
}
function gfxRainDark(){ return isDay()?((typeof tod==='function'&&tod())?(tod().lights||0):0):1; }
function gfxSplashDraw(){
  var m=GFXE.wm, WX=wx(), r=Math.min(2,(WX&&WX.rain)||0), Z=ZOOM(), t=G.t||0, n=0, N, k, u, c, f, Lf, x, y, s, A, spr, vx0, vy0, vw, vh;
  if(!m||!(r>0.05)) return 0;
  N=Math.round((CFG.fxLevel===0)?(10+12*r):(24+30*r));
  Lf=(r>1)?0.3:0.38;
  A=0.55*Math.min(1,r)*(1-0.45*gfxRainDark());
  vx0=VX-20; vy0=VY-20; vw=W/Z+40; vh=H/Z+40;
  spr=gfxSplashSpr();
  wc.save(); wc.setTransform(m.a,m.b,m.c,m.d,m.e,m.f);
  for(k=0;k<N;k++){
    u=t/Lf+k*0.6180339; c=Math.floor(u); f=u-c;
    x=vx0+gfxH2(k,c)*vw; y=vy0+gfxH2(k+71.3,c)*vh;
    s=(6+17*f)*(r>1?1.15:1);
    wc.globalAlpha=Math.max(0,Math.min(1,A*(1-f*f)));
    wc.drawImage(spr,x-s,y-s*0.45,s*2,s*0.9);
    n++;
  }
  wc.restore();
  return n;
}
function gfxRainFar(){
  var WX=wx(), r=Math.min(2,(WX&&WX.rain)||0), t=G.t||0, i, N, rx, ry, rl;
  if(!(r>0.05)) return 0;
  N=Math.round(((CFG.fxLevel===0)?40:80)+60*r);
  rl=r>1?11:8;
  wc.save();
  wc.globalAlpha=1; wc.globalCompositeOperation='source-over';
  wc.strokeStyle='rgba(150,170,205,'+((0.10+r*0.05)*Math.min(1,r)*(1-0.45*gfxRainDark())).toFixed(3)+')';
  wc.lineWidth=0.8;
  wc.beginPath();
  for(i=0;i<N;i++){
    rx=((i*53.71+t*(r>1?250:150))%(W+80))-40;
    ry=((i*89.3+t*(r>1?590:370))%(H+60))-30;
    wc.moveTo(rx,ry); wc.lineTo(rx-rl*0.28,ry+rl);
  }
  wc.stroke();
  wc.restore();
  return 1;
}
// ===== GFX-E end =====

